import XCTest
@testable import Tern

final class NativeCoreTrustTunnelTests: XCTestCase {

    // MARK: - 1. Positive Cases: Deep Link Decoding

    func testDeepLinkMinimal() {
        // Test vector generated by official TrustTunnel python tooling
        // hostname: vpn.example.com, addresses: 1.2.3.4:443, username: alice, password: secret123
        let uri = "tt://?AAECAQ92cG4uZXhhbXBsZS5jb20FBWFsaWNlBglzZWNyZXQxMjMCCzEuMi4zLjQ6NDQz"
        guard let proxy = NCTrustTunnel.parseDeepLink(uri) else {
            XCTFail("Failed to parse minimal deep link")
            return
        }

        XCTAssertEqual(proxy.type, "trusttunnel")
        XCTAssertEqual(proxy.name, "vpn.example.com")
        XCTAssertEqual(proxy.server, "1.2.3.4")
        XCTAssertEqual(proxy.port, 443)
        XCTAssertEqual(proxy.fields["username"]?.string, "alice")
        XCTAssertEqual(proxy.password, "secret123")
        XCTAssertEqual(proxy.fields["quic"]?.bool, false)
        XCTAssertEqual(proxy.fields["network"]?.string, "h2")
        XCTAssertEqual(proxy.fields["skip-cert-verify"]?.bool, false)
        XCTAssertEqual(proxy.fields["has-ipv6"]?.bool, true)
        XCTAssertEqual(proxy.fields["sni"]?.string, "vpn.example.com")
    }

    func testDeepLinkMaximal() {
        // Test vector generated by official TrustTunnel python tooling
        // hostname: vpn.example.com, addresses: 1.2.3.4:443, username: bob, password: pass456,
        // custom_sni: sni.example.com, skip_verification: true, upstream_protocol: http3,
        // name: My TrustTunnel Node, dns_upstreams: [1.1.1.1, https://dns.google/dns-query]
        let uri = "tt://?AAECAQ92cG4uZXhhbXBsZS5jb20FA2JvYgYHcGFzczQ1NgILMS4yLjMuNDo0NDMDD3NuaS5leGFtcGxlLmNvbQcBAQkBAgwTTXkgVHJ1c3RUdW5uZWwgTm9kZQ0lBzEuMS4xLjEcaHR0cHM6Ly9kbnMuZ29vZ2xlL2Rucy1xdWVyeQ"
        guard let proxy = NCTrustTunnel.parseDeepLink(uri) else {
            XCTFail("Failed to parse maximal deep link")
            return
        }

        XCTAssertEqual(proxy.type, "trusttunnel")
        XCTAssertEqual(proxy.name, "My TrustTunnel Node")
        XCTAssertEqual(proxy.server, "1.2.3.4")
        XCTAssertEqual(proxy.port, 443)
        XCTAssertEqual(proxy.fields["username"]?.string, "bob")
        XCTAssertEqual(proxy.password, "pass456")
        XCTAssertEqual(proxy.fields["custom-sni"]?.string, "sni.example.com")
        XCTAssertEqual(proxy.fields["sni"]?.string, "sni.example.com")
        XCTAssertEqual(proxy.fields["servername"]?.string, "sni.example.com")
        XCTAssertEqual(proxy.fields["quic"]?.bool, true)
        XCTAssertEqual(proxy.fields["network"]?.string, "h3")
        XCTAssertEqual(proxy.fields["skip-cert-verify"]?.bool, true)

        let dns = proxy.fields["dns-upstreams"]?.array?.compactMap { $0.string } ?? []
        XCTAssertEqual(dns, ["1.1.1.1", "https://dns.google/dns-query"])
    }

    func testDeepLinkSubscriptionOnly() {
        // Test vector: subscription_url = "https://user:pass@vpn.example.com/sub"
        let uri = "tt://?AAECDiVodHRwczovL3VzZXI6cGFzc0B2cG4uZXhhbXBsZS5jb20vc3Vi"
        guard let proxy = NCTrustTunnel.parseDeepLink(uri) else {
            XCTFail("Failed to parse subscription-only deep link")
            return
        }

        XCTAssertEqual(proxy.type, "trusttunnel")
        XCTAssertEqual(proxy.fields["subscription-url"]?.string, "https://user:pass@vpn.example.com/sub")
    }

    func testDeepLinkRoundtrip() {
        let original = NCTrustTunnel.encodeDeepLink(
            hostname: "edge.trusttunnel.org",
            addresses: ["198.51.100.1:8443", "198.51.100.2:8443"],
            username: "roundtrip_user",
            password: "rt_password_999",
            name: "RT Node",
            customSni: "custom.edge.org",
            hasIpv6: false,
            skipVerification: true,
            upstreamProtocol: 2, // HTTP/3
            antiDpi: true,
            clientRandomPrefix: "a0b0/f0f0",
            clientRandomAuthKey: "0011223344556677",
            dnsUpstreams: ["8.8.8.8", "https://dns.google/dns-query"],
            subscriptionUrl: "https://edge.trusttunnel.org/subscription"
        )

        guard let decoded = NCTrustTunnel.parseDeepLink(original) else {
            XCTFail("Failed to decode roundtrip deep link")
            return
        }

        XCTAssertEqual(decoded.name, "RT Node")
        XCTAssertEqual(decoded.server, "198.51.100.1")
        XCTAssertEqual(decoded.port, 8443)
        XCTAssertEqual(decoded.fields["username"]?.string, "roundtrip_user")
        XCTAssertEqual(decoded.password, "rt_password_999")
        XCTAssertEqual(decoded.fields["sni"]?.string, "custom.edge.org")
        XCTAssertEqual(decoded.fields["has-ipv6"]?.bool, false)
        XCTAssertEqual(decoded.fields["skip-cert-verify"]?.bool, true)
        XCTAssertEqual(decoded.fields["quic"]?.bool, true)
        XCTAssertEqual(decoded.fields["network"]?.string, "h3")
        XCTAssertEqual(decoded.fields["anti-dpi"]?.bool, true)
        XCTAssertEqual(decoded.fields["client-random-prefix"]?.string, "a0b0/f0f0")
        XCTAssertEqual(decoded.fields["client-random-auth-key"]?.string, "0011223344556677")
        XCTAssertEqual(decoded.fields["subscription-url"]?.string, "https://edge.trusttunnel.org/subscription")

        let addrs = decoded.fields["addresses"]?.array?.compactMap { $0.string } ?? []
        XCTAssertEqual(addrs, ["198.51.100.1:8443", "198.51.100.2:8443"])
    }

