    // MARK: - 5. Negative Cases: Deep Link & URI Rejection

    func testDeepLinkMissingRequiredFields() {
        // Missing password
        var d1 = Data()
        d1.append(NCTrustTunnel.writeVarInt(0x01))
        let hData = Data("host.com".utf8)
        d1.append(NCTrustTunnel.writeVarInt(UInt64(hData.count)))
        d1.append(hData)
        d1.append(NCTrustTunnel.writeVarInt(0x02))
        let aData = Data("1.2.3.4:443".utf8)
        d1.append(NCTrustTunnel.writeVarInt(UInt64(aData.count)))
        d1.append(aData)
        d1.append(NCTrustTunnel.writeVarInt(0x05))
        let uData = Data("user".utf8)
        d1.append(NCTrustTunnel.writeVarInt(UInt64(uData.count)))
        d1.append(uData)
        // No tag 0x06 (password)

        let uri1 = "tt://?" + NCTrustTunnel.base64URLEncode(d1)
        XCTAssertNil(NCTrustTunnel.parseDeepLink(uri1), "Expected rejection when password is missing")

        // Missing username
        var d2 = Data()
        d2.append(NCTrustTunnel.writeVarInt(0x01))
        d2.append(NCTrustTunnel.writeVarInt(UInt64(hData.count)))
        d2.append(hData)
        d2.append(NCTrustTunnel.writeVarInt(0x02))
        d2.append(NCTrustTunnel.writeVarInt(UInt64(aData.count)))
        d2.append(aData)
        d2.append(NCTrustTunnel.writeVarInt(0x06))
        let pData = Data("pass".utf8)
        d2.append(NCTrustTunnel.writeVarInt(UInt64(pData.count)))
        d2.append(pData)
        // No tag 0x05 (username)

        let uri2 = "tt://?" + NCTrustTunnel.base64URLEncode(d2)
        XCTAssertNil(NCTrustTunnel.parseDeepLink(uri2), "Expected rejection when username is missing")

        // Missing addresses (and no subscription_url)
        var d3 = Data()
        d3.append(NCTrustTunnel.writeVarInt(0x01))
        d3.append(NCTrustTunnel.writeVarInt(UInt64(hData.count)))
        d3.append(hData)
        d3.append(NCTrustTunnel.writeVarInt(0x05))
        d3.append(NCTrustTunnel.writeVarInt(UInt64(uData.count)))
        d3.append(uData)
        d3.append(NCTrustTunnel.writeVarInt(0x06))
        d3.append(NCTrustTunnel.writeVarInt(UInt64(pData.count)))
        d3.append(pData)

        let uri3 = "tt://?" + NCTrustTunnel.base64URLEncode(d3)
        XCTAssertNil(NCTrustTunnel.parseDeepLink(uri3), "Expected rejection when addresses are missing")
    }

    func testDeepLinkUnsupportedVersion() {
        // Tag 0x00 with version = 3 (CURRENT_VERSION is 2)
        var d = Data()
        d.append(NCTrustTunnel.writeVarInt(0x00))
        let vData = NCTrustTunnel.writeVarInt(3)
        d.append(NCTrustTunnel.writeVarInt(UInt64(vData.count)))
        d.append(vData)

        let uri = "tt://?" + NCTrustTunnel.base64URLEncode(d)
        XCTAssertNil(NCTrustTunnel.parseDeepLink(uri), "Expected rejection when version exceeds supported version 2")
    }

    func testDeepLinkInvalidSubscriptionUrl() {
        // subscription_url must start with https:// per DEEP_LINK.md
        var d = Data()
        d.append(NCTrustTunnel.writeVarInt(0x0e))
        let sData = Data("http://insecure.example.com/sub".utf8)
        d.append(NCTrustTunnel.writeVarInt(UInt64(sData.count)))
        d.append(sData)

        let uri = "tt://?" + NCTrustTunnel.base64URLEncode(d)
        XCTAssertNil(NCTrustTunnel.parseDeepLink(uri), "Expected rejection when subscription_url is not https://")
    }

    func testDeepLinkCorruptedPayload() {
        XCTAssertNil(NCTrustTunnel.parseDeepLink("tt://?***corrupted***"))
        XCTAssertNil(NCTrustTunnel.parseDeepLink("tt://?"))
        XCTAssertNil(NCTrustTunnel.parseDeepLink("invalid://foo"))
    }

    // MARK: - 6. Quantumult X Rejection

    func testQuantumultXRejection() {
        let qxLine = "trusttunnel=1.2.3.4:443, password=testpass, tag=QX-TT"
        var report = NCImportReport()
        let node = NCQXImport.buildQXNode(line: qxLine, report: &report)

        XCTAssertNil(node, "Quantumult X buildQXNode must return nil for trusttunnel")
        XCTAssertTrue(
            report.warnings.contains { $0.contains("trusttunnel has no Quantumult X format specification; explicitly unavailable") },
            "Report warnings must record explicit unavailability for trusttunnel"
        )

        // Hyphen alias
        let qxLine2 = "trust-tunnel=1.2.3.4:443, password=testpass, tag=QX-TT2"
        var report2 = NCImportReport()
        let node2 = NCQXImport.buildQXNode(line: qxLine2, report: &report2)
        XCTAssertNil(node2)
        XCTAssertTrue(
            report2.warnings.contains { $0.contains("trusttunnel has no Quantumult X format specification; explicitly unavailable") }
        )
    }

    // MARK: - 7. Unsupported Fields & Validation Markers

    func testUnsupportedFieldMarkers() {
        // Valid baseline node
        let validNode = NCProxy(name: "Valid", type: "trusttunnel", fields: [
            "server": .string("1.2.3.4"),
            "port": .number(443),
            "username": .string("valid_user"),
            "password": .string("valid_pass")
        ])
        XCTAssertNil(NCSupport.unsupportedReason(validNode), "Valid node should have no unsupported reason")

        // Missing server
        let noServer = NCProxy(name: "NoServer", type: "trusttunnel", fields: [
            "port": .number(443),
            "username": .string("u"),
            "password": .string("p")
        ])
        XCTAssertEqual(NCSupport.unsupportedReason(noServer), "TrustTunnel 缺少 server")

        // Missing port
        let noPort = NCProxy(name: "NoPort", type: "trusttunnel", fields: [
            "server": .string("1.2.3.4"),
            "username": .string("u"),
            "password": .string("p")
        ])
        XCTAssertEqual(NCSupport.unsupportedReason(noPort), "TrustTunnel 缺少 port")

        // Missing username
        let noUser = NCProxy(name: "NoUser", type: "trusttunnel", fields: [
            "server": .string("1.2.3.4"),
            "port": .number(443),
            "password": .string("p")
        ])
        XCTAssertEqual(NCSupport.unsupportedReason(noUser), "TrustTunnel 缺少 username")

        // Missing password
        let noPass = NCProxy(name: "NoPass", type: "trusttunnel", fields: [
            "server": .string("1.2.3.4"),
            "port": .number(443),
            "username": .string("u")
        ])
        XCTAssertEqual(NCSupport.unsupportedReason(noPass), "TrustTunnel 缺少 password")

        // Anti-DPI unsupported marker
        let antiDpiNode = NCProxy(name: "AntiDPI", type: "trusttunnel", fields: [
            "server": .string("1.2.3.4"),
            "port": .number(443),
            "username": .string("u"),
            "password": .string("p"),
            "anti-dpi": .bool(true)
        ])
        XCTAssertEqual(NCSupport.unsupportedReason(antiDpiNode), "TrustTunnel anti-dpi / client-random-prefix 尚未接入")

        // Client random prefix unsupported marker
        let prefixNode = NCProxy(name: "Prefix", type: "trusttunnel", fields: [
            "server": .string("1.2.3.4"),
            "port": .number(443),
            "username": .string("u"),
            "password": .string("p"),
            "client-random-prefix": .string("a0b0/f0f0")
        ])
        XCTAssertEqual(NCSupport.unsupportedReason(prefixNode), "TrustTunnel anti-dpi / client-random-prefix 尚未接入")

        // Client random auth key unsupported marker
        let authKeyNode = NCProxy(name: "AuthKey", type: "trusttunnel", fields: [
            "server": .string("1.2.3.4"),
            "port": .number(443),
            "username": .string("u"),
            "password": .string("p"),
            "client-random-auth-key": .string("0123456789abcdef")
        ])
        XCTAssertEqual(NCSupport.unsupportedReason(authKeyNode), "TrustTunnel client-random-auth-key 尚未接入")

        // ICMP unsupported marker
        let icmpNode = NCProxy(name: "ICMP", type: "trusttunnel", fields: [
            "server": .string("1.2.3.4"),
            "port": .number(443),
            "username": .string("u"),
            "password": .string("p"),
            "icmp": .bool(true)
        ])
        XCTAssertEqual(NCSupport.unsupportedReason(icmpNode), "TrustTunnel icmp 尚未接入")
    }

    // MARK: - 8. Wire Framing Tests

    func testWireFraming() {
        // CONNECT headers verification
        let headers = NCTrustTunnelWire.connectHeaders(
            authority: "target.com:443",
            username: "testuser",
            password: "testpassword"
        )
        let headerMap = Dictionary(headers, uniquingKeysWith: { a, _ in a })
        XCTAssertEqual(headerMap[":method"], "CONNECT")
        XCTAssertEqual(headerMap[":authority"], "target.com:443")
        let expectedCreds = Data("testuser:testpassword".utf8).base64EncodedString()
        XCTAssertEqual(headerMap["proxy-authorization"], "Basic \(expectedCreds)")

        // UDP pseudo-host headers
        let udpHeaders = NCTrustTunnelWire.connectHeaders(
            authority: NCTrustTunnelWire.udpPseudoHost,
            username: "u",
            password: "p"
        )
        let udpHeaderMap = Dictionary(udpHeaders, uniquingKeysWith: { a, _ in a })
        XCTAssertEqual(udpHeaderMap[":authority"], "_udp2")
        XCTAssertEqual(udpHeaderMap["user-agent"], "iOS _udp2")

        // IP padding verification: IPv4 must be zero-padded to 16 bytes
        let v4Padded = NCTrustTunnelWire.padIPAddress("192.0.2.1")!
        XCTAssertEqual(v4Padded.count, 16)
        XCTAssertEqual(v4Padded.prefix(12), Data(count: 12))
        XCTAssertEqual(Array(v4Padded.suffix(4)), [192, 0, 2, 1])

        // IPv6 16 bytes
        let v6Padded = NCTrustTunnelWire.padIPAddress("2001:db8::1")!
        XCTAssertEqual(v6Padded.count, 16)

        // UDP Outgoing Packet (Client -> Endpoint) encode / decode roundtrip
        let srcIP = v4Padded
        let dstIP = v6Padded
        let payload = Data("hello trusttunnel udp".utf8)
        let clientWireData = NCTrustTunnelWire.encodeClientPacket(
            srcIP: srcIP,
            srcPort: 54321,
            dstIP: dstIP,
            dstPort: 53,
            appName: "com.apple.mobilesafari",
            payload: payload
        )

        var off1 = 0
        guard let clientPacket = NCTrustTunnelWire.decodeClientPacket(data: clientWireData, offset: &off1) else {
            XCTFail("Failed to decode client UDP packet")
            return
        }

        XCTAssertEqual(clientPacket.srcIP, srcIP)
        XCTAssertEqual(clientPacket.srcPort, 54321)
        XCTAssertEqual(clientPacket.dstIP, dstIP)
        XCTAssertEqual(clientPacket.dstPort, 53)
        XCTAssertEqual(clientPacket.appName, "com.apple.mobilesafari")
        XCTAssertEqual(clientPacket.payload, payload)
        XCTAssertEqual(off1, clientWireData.count)

        // UDP Incoming Packet (Endpoint -> Client) encode / decode roundtrip
        let serverWireData = NCTrustTunnelWire.encodeServerPacket(
            srcIP: dstIP,
            srcPort: 53,
            dstIP: srcIP,
            dstPort: 54321,
            payload: payload
        )

        var off2 = 0
        guard let serverPacket = NCTrustTunnelWire.decodeServerPacket(data: serverWireData, offset: &off2) else {
            XCTFail("Failed to decode server UDP packet")
            return
        }

        XCTAssertEqual(serverPacket.srcIP, dstIP)
        XCTAssertEqual(serverPacket.srcPort, 53)
        XCTAssertEqual(serverPacket.dstIP, srcIP)
        XCTAssertEqual(serverPacket.dstPort, 54321)
        XCTAssertEqual(serverPacket.payload, payload)
        XCTAssertEqual(off2, serverWireData.count)
    }

    // MARK: - S2 Single-Test Reinforcements

    func testFrameCodecBoundaries() {
        // Truncated UDP packet decoding (less than 4-byte length)
        var off0 = 0
        XCTAssertNil(NCTrustTunnelWire.decodeServerPacket(data: Data([0x00, 0x00]), offset: &off0))
        XCTAssertNil(NCTrustTunnelWire.decodeClientPacket(data: Data([0x00, 0x00, 0x01]), offset: &off0))

        // Length claims 100 bytes, but buffer has only 10 bytes
        var offLenOverflow = 0
        var truncatedBuf = Data()
        truncatedBuf.appendBE32(100)
        truncatedBuf.append(Data(repeating: 0xaa, count: 6))
        XCTAssertNil(NCTrustTunnelWire.decodeServerPacket(data: truncatedBuf, offset: &offLenOverflow))
        XCTAssertNil(NCTrustTunnelWire.decodeClientPacket(data: truncatedBuf, offset: &offLenOverflow))

        // Length less than minimum header (36 bytes for server)
        var offTooShort = 0
        var tooShortBuf = Data()
        tooShortBuf.appendBE32(30)
        tooShortBuf.append(Data(repeating: 0xaa, count: 30))
        XCTAssertNil(NCTrustTunnelWire.decodeServerPacket(data: tooShortBuf, offset: &offTooShort))

        // Client packet: appName length overflow
        var offAppOverflow = 0
        var appOverflowBuf = Data()
        appOverflowBuf.appendBE32(40) // total payload 40 bytes
        appOverflowBuf.append(Data(count: 16)) // srcIP
        appOverflowBuf.appendBE16(1234)        // srcPort
        appOverflowBuf.append(Data(count: 16)) // dstIP
        appOverflowBuf.appendBE16(80)          // dstPort
        appOverflowBuf.append(50)              // appLen = 50, but remaining length is only 40 - 37 = 3 bytes
        appOverflowBuf.append(Data(count: 3))
        XCTAssertNil(NCTrustTunnelWire.decodeClientPacket(data: appOverflowBuf, offset: &offAppOverflow))

        // Invalid IP address padding
        XCTAssertNil(NCTrustTunnelWire.padIPAddress("not-an-ip"))
        XCTAssertNil(NCTrustTunnelWire.padIPAddress("999.999.999.999"))

        // VarInt boundary tests
        let boundaryValues: [UInt64] = [
            0,
            63,
            64,
            16383,
            16384,
            (1 << 30) - 1,
            (1 << 30),
            (UInt64(1) << 62) - 1
        ]
        for val in boundaryValues {
            let encoded = NCTrustTunnel.writeVarInt(val)
            var decOff = 0
            let decoded = NCTrustTunnel.readVarInt(data: encoded, offset: &decOff)
            XCTAssertEqual(decoded, val, "VarInt roundtrip mismatch for \(val)")
            XCTAssertEqual(decOff, encoded.count)
        }

        // Truncated VarInt tests
        var truncOff = 0
        // Prefix 1 (2 bytes expected, only 1 provided)
        XCTAssertNil(NCTrustTunnel.readVarInt(data: Data([0x40]), offset: &truncOff))
        // Prefix 2 (4 bytes expected, only 3 provided)
        truncOff = 0
        XCTAssertNil(NCTrustTunnel.readVarInt(data: Data([0x80, 0x01, 0x02]), offset: &truncOff))
        // Prefix 3 (8 bytes expected, only 6 provided)
        truncOff = 0
        XCTAssertNil(NCTrustTunnel.readVarInt(data: Data([0xc0, 0x01, 0x02, 0x03, 0x04, 0x05]), offset: &truncOff))
    }

    func testQPACKConnectHeadersRoundtrip() {
        let authority = "echo.example.com:8443"
        let user = "testuser"
        let pass = "testpass123"
        let qpackData = NCTrustTunnelWire.qpackConnectHeaders(
            authority: authority,
            username: user,
            password: pass
        )

        guard let fields = NCHy2.qpackDecodeFieldSection(qpackData) else {
            XCTFail("Failed to decode QPACK field section")
            return
        }

        let fieldMap = Dictionary(fields, uniquingKeysWith: { first, _ in first })
        XCTAssertEqual(fieldMap[":method"], "CONNECT")
        XCTAssertEqual(fieldMap[":authority"], authority)
        let expectedCreds = Data("\(user):\(pass)".utf8).base64EncodedString()
        XCTAssertEqual(fieldMap["proxy-authorization"], "Basic \(expectedCreds)")
        XCTAssertEqual(fieldMap["user-agent"], "iOS TrustTunnel")
    }

    func testAuthenticationFailurePaths() {
        // H2 407 response handling: verify status 407 error extraction
        let h2Headers407: [(String, String)] = [
            (":status", "407"),
            ("proxy-authenticate", "Basic realm=\"TrustTunnel\"")
        ]
        let status = h2Headers407.first { $0.0 == ":status" }?.1
        XCTAssertEqual(status, "407")

        // H3 407 response handling: QPACK encode status 407
        var qpack407 = Data([0x00, 0x00]) // ric 0, base 0
        qpack407.append(NCHy2.qpackEncodeString(":status", prefixBits: 3, flags: 0x20))
        qpack407.append(NCHy2.qpackEncodeString("407"))

        let decodedFields = NCHy2.qpackDecodeFieldSection(qpack407)
        XCTAssertNotNil(decodedFields)
        let statusField = decodedFields?.first { $0.name == ":status" }?.value
        XCTAssertEqual(statusField, "407")

        // H3 200 response handling
        var qpack200 = Data([0x00, 0x00])
        qpack200.append(NCHy2.qpackEncodeInteger(25, prefixBits: 6, flags: 0xC0))
        let decoded200 = NCHy2.qpackDecodeFieldSection(qpack200)
        XCTAssertNotNil(decoded200)
        let status200 = decoded200?.first { $0.name == ":status" }?.value
        XCTAssertEqual(status200, "200")
    }

    // MARK: - fix/nc-proto-trusttunnel-int

    /// The HTTP/3 track is not finished (no control stream, payload not in DATA frames, stream not retained
    /// through the handshake): quic / network h3 nodes are shown unavailable, HTTP/2 stays available.
    func testHTTP3TrackIsUnavailable() {
        let base: [String: NCJSONValue] = ["server": .string("1.2.3.4"), "port": .number(443),
                                           "username": .string("u"), "password": .string("p")]
        var quic = base; quic["quic"] = .bool(true)
        var h3 = base; h3["network"] = .string("h3")
        var h2 = base; h2["network"] = .string("h2")
        XCTAssertNotNil(NCSupport.unsupportedReason(NCProxy(name: "q", type: "trusttunnel", fields: quic)))
        XCTAssertNotNil(NCSupport.unsupportedReason(NCProxy(name: "h", type: "trusttunnel", fields: h3)))
        XCTAssertNil(NCSupport.unsupportedReason(NCProxy(name: "h2", type: "trusttunnel", fields: h2)))
    }
}
